<?php
require_once __DIR__ . '/_layout.php';requirePermission('contracts.manage');
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if($action==='generate'){$id=createContractFromReservation((int)($_POST['reservation_id']??0),$_POST['language']??'fr');flash('success','Contract generated: #'.$id);}elseif($action==='amend'){$version=amendContract((int)$_POST['id'],trim((string)($_POST['reason']??'')),$_POST['language']??'fr');flash('success','Contract amendment version '.$version.' created.');}elseif($action==='status'){$id=(int)$_POST['id'];$contract=dbFetchOne('SELECT rc.*,r.agency_id FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id WHERE rc.id=:id',['id'=>$id]);if(!$contract)throw new InvalidArgumentException('Contract not found.');requireAgencyAccess($contract['agency_id']);$status=validateChoice($_POST['status']??'',contractStatuses(),null);if(!$status)throw new InvalidArgumentException('Invalid contract status.');if(in_array($contract['status'],['signed','active','completed'],true)&&$status==='draft')throw new DomainException('A signed contract cannot be returned to draft. Create an amendment instead.');dbExecute('UPDATE rental_contracts SET status=:status,signed_at=IF(:status2=\'signed\',NOW(),signed_at),completed_at=IF(:status3=\'completed\',NOW(),completed_at),cancelled_at=IF(:status4=\'cancelled\',NOW(),cancelled_at),cancellation_reason=:reason,updated_by=:user WHERE id=:id',['status'=>$status,'status2'=>$status,'status3'=>$status,'status4'=>$status,'reason'=>$status==='cancelled'?trim((string)($_POST['reason']??'')):null,'user'=>currentUserId(),'id'=>$id]);auditLog('contract.status_changed','contract',$id,['status'=>$contract['status']],['status'=>$status],$contract['agency_id']);flash('success','Contract status updated.');}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Contract operation failed');flash('danger','The contract operation could not be completed.');}safeRedirect('contracts.php');}
$agencyIds=currentAgencyIds();$placeholders=implode(',',array_fill(0,count($agencyIds),'?'));if(!$agencyIds)$agencyIds=[0];$eligible=dbFetchAll("SELECT r.id,r.reference,c.first_name,c.last_name FROM reservations r JOIN customers c ON c.id=r.customer_id LEFT JOIN rental_contracts rc ON rc.reservation_id=r.id AND rc.status<>'cancelled' WHERE r.agency_id IN ($placeholders) AND r.status IN ('confirmed','deposit_paid','ready') AND rc.id IS NULL ORDER BY r.created_at DESC",$agencyIds);$contracts=dbFetchAll("SELECT rc.*,r.reference,r.agency_id,c.first_name,c.last_name,v.registration_number FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN customers c ON c.id=r.customer_id LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.agency_id IN ($placeholders) ORDER BY rc.created_at DESC LIMIT 100",$agencyIds);
backofficeHeader(t('contracts'),'contracts.php');?><?php pageHeader(t('contracts'), 'Generate, sign, amend, and print rental agreements.', ['breadcrumbs'=>[['label'=>'Rentals'],['label'=>'contracts']],'primary'=>['label'=>'Generate contract','href'=>'#new-contract']]); ?><div class="grid"><section class="card" id="new-contract"><h2>Generate from reservation</h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="generate"><label>Reservation<select name="reservation_id" required><?php foreach($eligible as $row):?><option value="<?=e($row['id'])?>"><?=e($row['reference'].' — '.$row['first_name'].' '.$row['last_name'])?></option><?php endforeach;?></select></label><label>Contract language<select name="language"><option value="fr">Français</option><option value="ar">العربية</option><option value="en">English</option></select></label><button class="btn primary">Generate contract</button></form></section><section class="card"><h2>Contract register</h2><div class="table-wrap"><table><tr><th>Number</th><th>Reservation</th><th>Customer</th><th>Vehicle</th><th>Version</th><th>Status</th><th>Documents</th></tr><?php foreach($contracts as $contract):?><tr><td><?=e($contract['contract_number'])?></td><td><?=e($contract['reference'])?></td><td><?=e($contract['first_name'].' '.$contract['last_name'])?></td><td><?=e($contract['registration_number'])?></td><td><?=e($contract['current_version'])?></td><td><?=statusBadge($contract['status'])?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=e($contract['id'])?>"><select name="status"><?php foreach(contractStatuses() as $status):?><option <?=$status===$contract['status']?'selected':''?>><?=e($status)?></option><?php endforeach;?></select><input name="reason" placeholder="Reason"><button class="btn secondary">Update</button></form></td><td><a class="btn secondary" href="contract_print.php?id=<?=e($contract['id'])?>&lang=fr" target="_blank">Print / PDF</a><?php if(in_array($contract['status'],['signed','active','amended'],true)):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="amend"><input type="hidden" name="id" value="<?=e($contract['id'])?>"><input type="hidden" name="language" value="fr"><input name="reason" required placeholder="Amendment reason"><button class="btn secondary">Create amendment</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php if(!$contracts):?><p class="empty"><?=e(t('no_results'))?></p><?php endif;?></div></section></div><?php backofficeFooter();

